preConditionHook:
// EEC E23's Stochastic at SmoothingType 1 ("original"), the `stochastic`
// register row (VERIFIED, EL_Stochastic_Probe.txt, two chart starts):
//   oFastK  = 100 * (C - LL(sLength)) / (HH - LL)          -- fresh, real
//             price history (5.1e-13 against the probe);
//   oSlowK == oFastD = 100 * Sum(C - LL, smoothing1) / Sum(HH - LL,
//             smoothing1) -- a RATIO OF SUMS of the per-bar numerator and
//             denominator, NOT an average of FastK (that model was refuted
//             at maxd 24);
//   oSlowD  = simple smoothing2-mean of SlowK.
// WARM-UP (measured exactly, 0/61 bars, by joining run 2's early bars with
// run 1's pre-history): the num/den/SlowK series exist only from the
// study's first calculated bar, and missing terms are SEED-FILLED with the
// FIRST bar's value -- not zero-filled: a short sum adds (N - have) copies
// of element [0], and SlowD's mean pads with the first SlowK the same way.
// The growing vectors below reproduce that: they start empty at the first
// evaluated bar and never see pre-study bars.
double hhWin = high[0];
double llWin = low[0];
for (int i = 1; i < (int)sLength; ++i) {
    if (el_gt(high[i], hhWin)) { hhWin = high[i]; }
    if (el_lt(low[i], llWin)) { llWin = low[i]; }
}
skNumHist.push_back(close[0] - llWin);
skDenHist.push_back(hhWin - llWin);
double skSumN = 0.0;
double skSumD = 0.0;
{
    int have = (int)skNumHist.size();
    int take = have < (int)smoothing1 ? have : (int)smoothing1;
    for (int i = 0; i < take; ++i) {  // newest-first
        skSumN += skNumHist[skNumHist.size() - 1 - i];
        skSumD += skDenHist[skDenHist.size() - 1 - i];
    }
    int miss = (int)smoothing1 - take;
    if (miss > 0) {
        skSumN += miss * skNumHist[0];
        skSumD += miss * skDenHist[0];
    }
}
// An all-flat sLength window across the whole sum makes the denominator 0;
// EL raises there (the zero-denominator register row) and this mirror does
// not guard either -- unreachable on real data.
slowK = 100.0 * skSumN / skSumD;
skHist.push_back(slowK);
double skSumK = 0.0;
{
    int have = (int)skHist.size();
    int take = have < (int)smoothing2 ? have : (int)smoothing2;
    for (int i = 0; i < take; ++i) {  // newest-first
        skSumK += skHist[skHist.size() - 1 - i];
    }
    int miss = (int)smoothing2 - take;
    if (miss > 0) { skSumK += miss * skHist[0]; }
}
slowD = skSumK / (int)smoothing2;
// EL `crosses` is a STATE MACHINE (the `crosses over/under` register row,
// VERIFIED): fires when the toleranced comparison holds AND the most recent
// NON-equal bar was on the other side; equality runs are bridged; the side
// starts UNKNOWN (0), so nothing fires on the first evaluated bar.
crossUpKD = el_gt(slowK, slowD) && lastSideKD == -1;
crossDownKD = el_lt(slowK, slowD) && lastSideKD == 1;
if (el_gt(slowK, slowD)) { lastSideKD = 1; }
else if (el_lt(slowK, slowD)) { lastSideKD = -1; }
